class Solution {
    public boolean isBalanced(TreeNode root) {
        return heightOrUnbalanced(root) != -1;
    }

    private int heightOrUnbalanced(TreeNode node) {
        if (node == null) return 0;

        int left = heightOrUnbalanced(node.left);
        if (left == -1) return -1;

        int right = heightOrUnbalanced(node.right);
        if (right == -1) return -1;

        if (Math.abs(left - right) > 1) return -1;
        return 1 + Math.max(left, right);
    }
}

class Solution {
    public boolean isBalanced(TreeNode root) {
        if (root == null) return true;

        int leftHeight = height(root.left);
        int rightHeight = height(root.right);
        if (Math.abs(leftHeight - rightHeight) > 1) return false;

        return isBalanced(root.left) && isBalanced(root.right);
    }

    private int height(TreeNode node) {
        if (node == null) return 0;
        return 1 + Math.max(height(node.left), height(node.right));
    }
}

import java.util.*;

class Solution {
    public boolean isBalanced(TreeNode root) {
        Map<TreeNode, Integer> height = new HashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;
        TreeNode lastVisited = null;

        while (current != null || !stack.isEmpty()) {
            while (current != null) {
                stack.push(current);
                current = current.left;
            }

            TreeNode peek = stack.peek();
            if (peek.right != null && lastVisited != peek.right) {
                current = peek.right;
            } else {
                int leftHeight = height.getOrDefault(peek.left, 0);
                int rightHeight = height.getOrDefault(peek.right, 0);
                if (Math.abs(leftHeight - rightHeight) > 1) return false;
                height.put(peek, 1 + Math.max(leftHeight, rightHeight));
                lastVisited = stack.pop();
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public boolean isBalanced(TreeNode root) {
        if (root == null) return true;

        List<TreeNode> order = new ArrayList<>();
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            order.add(node);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }

        Map<TreeNode, Integer> height = new HashMap<>();
        for (int i = order.size() - 1; i >= 0; i--) {
            TreeNode node = order.get(i);
            int leftHeight = height.getOrDefault(node.left, 0);
            int rightHeight = height.getOrDefault(node.right, 0);
            if (Math.abs(leftHeight - rightHeight) > 1) return false;
            height.put(node, 1 + Math.max(leftHeight, rightHeight));
        }
        return true;
    }
}
